  ('he', 'admin.servicesGuide.coaching.sees', U&'\05D4\05D4\05D5\05E8\05D4 \05E7\05D5\05D1\05E2 \05DE\05E4\05D2\05E9\05D9\05DD \05D1\05E2\05E6\05DE\05D5 \05DE\05EA\05D5\05DA \05D4\05D6\05DE\05E0\05D9\05DD \05D4\05E4\05E0\05D5\05D9\05D9\05DD \05E9\05DC \05D4\05DE\05D8\05E4\05DC\05EA, \05D5\05E8\05D5\05D0\05D4 \05D0\05EA \05D4\05DE\05E4\05D2\05E9\05D9\05DD \05D5\05D4\05EA\05E9\05DC\05D5\05DE\05D9\05DD.'),
  ('en', 'admin.servicesGuide.coaching.pay', U&'The card is saved at enrollment, and each session is charged only after it took place. Nothing is paid upfront.'),
  ('he', 'admin.servicesGuide.coaching.pay', U&'\05D4\05DB\05E8\05D8\05D9\05E1 \05E0\05E9\05DE\05E8 \05D1\05D4\05E8\05E9\05DE\05D4, \05D5\05DB\05DC \05DE\05E4\05D2\05E9 \05E0\05D2\05D1\05D4 \05E8\05E7 \05D0\05D7\05E8\05D9 \05E9\05D4\05EA\05E7\05D9\05D9\05DD. \05DC\05D0 \05DE\05E9\05DC\05DE\05D9\05DD \05DE\05E8\05D0\05E9.'),
  ('en', 'admin.servicesGuide.coaching.cta', U&'Go to therapists'),
  ('he', 'admin.servicesGuide.coaching.cta', U&'\05DE\05E2\05D1\05E8 \05DC\05DE\05D8\05E4\05DC\05D5\05EA'),
