  ('he', 'admin.servicesGuide.coaching.first', U&'\05D4\05DE\05D8\05E4\05DC\05D5\05EA \05D5\05D4\05E9\05E2\05D5\05EA \05E9\05DC\05D4\05DF'),
  ('en', 'admin.servicesGuide.coaching.step1.title', U&'Set up the therapists'),
