  ('en', 'admin.servicesGuide.coaching.step1.where', U&'Family guidance \2192 Therapists and hours'),
  ('he', 'admin.servicesGuide.coaching.step1.where', U&'\05D4\05D3\05E8\05DB\05EA \05DE\05E9\05E4\05D7\05D4 \2190 \05DE\05D8\05E4\05DC\05D5\05EA \05D5\05E9\05E2\05D5\05EA'),
  ('en', 'admin.servicesGuide.coaching.step1.choose', U&'A therapist is a user with the instructor role (added on the Users page). Here you set her working hours.'),
  ('he', 'admin.servicesGuide.coaching.step1.choose', U&'\05DE\05D8\05E4\05DC\05EA \05D4\05D9\05D0 \05DE\05E9\05EA\05DE\05E9\05EA \05E2\05DD \05EA\05E4\05E7\05D9\05D3 \05DE\05D3\05E8\05D9\05DA/\05D4 (\05DE\05D5\05E1\05D9\05E4\05D9\05DD \05D0\05D5\05EA\05D4 \05D1\05E2\05DE\05D5\05D3 "\05DE\05E9\05EA\05DE\05E9\05D9\05DD"). \05DB\05D0\05DF \05E7\05D5\05D1\05E2\05D9\05DD \05D0\05EA \05E9\05E2\05D5\05EA \05D4\05E2\05D1\05D5\05D3\05D4 \05E9\05DC\05D4.'),
  ('en', 'admin.servicesGuide.coaching.step2.title', U&'Create a guidance package'),
  ('he', 'admin.servicesGuide.coaching.step2.title', U&'\05D9\05D5\05E6\05E8\05D9\05DD \05D7\05D1\05D9\05DC\05EA \05DC\05D9\05D5\05D5\05D9'),
  ('en', 'admin.servicesGuide.coaching.step2.where', U&'Products \2192 New product'),
  ('he', 'admin.servicesGuide.coaching.step2.where', U&'\05DE\05D5\05E6\05E8\05D9\05DD \2190 \05DE\05D5\05E6\05E8 \05D7\05D3\05E9'),
  ('en', 'admin.servicesGuide.coaching.step2.choose', U&'Type: Session pack. Number of sessions and session length. Payment: per session (for example "CBT guidance").'),
  ('he', 'admin.servicesGuide.coaching.step2.choose', U&'\05E1\05D5\05D2: \05D7\05D1\05D9\05DC\05EA \05DE\05E4\05D2\05E9\05D9\05DD. \05DE\05E1\05E4\05E8 \05DE\05E4\05D2\05E9\05D9\05DD \05D5\05DE\05E9\05DA \05DE\05E4\05D2\05E9. \05EA\05E9\05DC\05D5\05DD: \05DC\05E4\05D9 \05DE\05E4\05D2\05E9 (\05DC\05DE\05E9\05DC "\05DC\05D9\05D5\05D5\05D9 CBT").'),
  ('en', 'admin.servicesGuide.coaching.step3.title', U&'Open a package for the client'),
  ('he', 'admin.servicesGuide.coaching.step3.title', U&'\05E4\05D5\05EA\05D7\05D9\05DD \05D7\05D1\05D9\05DC\05D4 \05DC\05DC\05E7\05D5\05D7'),
  ('en', 'admin.servicesGuide.coaching.step3.where', U&'Family guidance \2192 Open a package'),
  ('he', 'admin.servicesGuide.coaching.step3.where', U&'\05D4\05D3\05E8\05DB\05EA \05DE\05E9\05E4\05D7\05D4 \2190 \05E4\05EA\05D9\05D7\05EA \05D7\05D1\05D9\05DC\05D4'),
  ('en', 'admin.servicesGuide.coaching.step3.choose', U&'Choose parent guidance or child guidance, the client (and the child), the package and the therapist. The client gets an enrollment link: agreement, intake questionnaire and card. You can also open a package from a request sent from the portal.'),
  ('he', 'admin.servicesGuide.coaching.step3.choose', U&'\05D1\05D5\05D7\05E8\05D9\05DD \05DC\05D9\05D5\05D5\05D9 \05D4\05D5\05E8\05D9 \05D0\05D5 \05DC\05D9\05D5\05D5\05D9 \05D9\05DC\05D3\05D9\05DD, \05D0\05EA \05D4\05DC\05E7\05D5\05D7 (\05D5\05D0\05EA \05D4\05D9\05DC\05D3), \05D0\05EA \05D4\05D7\05D1\05D9\05DC\05D4 \05D5\05D0\05EA \05D4\05DE\05D8\05E4\05DC\05EA. \05D4\05DC\05E7\05D5\05D7 \05DE\05E7\05D1\05DC \05E7\05D9\05E9\05D5\05E8 \05DC\05D4\05E8\05E9\05DE\05D4: \05D7\05D5\05D6\05D4, \05E9\05D0\05DC\05D5\05DF \05E4\05EA\05D9\05D7\05D4 \05D5\05DB\05E8\05D8\05D9\05E1. \05D0\05E4\05E9\05E8 \05D2\05DD \05DC\05E4\05EA\05D5\05D7 \05D7\05D1\05D9\05DC\05D4 \05DE\05D1\05E7\05E9\05D4 \05E9\05D4\05D2\05D9\05E2\05D4 \05DE\05D4\05E4\05D5\05E8\05D8\05DC.')
) AS v(lang, key, value)
